#include <stdio.h>
#include <errno.h>
int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 1;
    if (n < 0) {
        errno = EINVAL;
        printf("ERROR_CODE %d\n", errno);
    } else {
        printf("OK %d\n", n);
    }
    return 0;
}

